   108→        return Err(ConsensusError::BodyBloomLogDiff(
   109→            GotExpected { got: calculated_logs_bloom, expected: expected_logs_bloom }.into(),
   110→        ))
   111→    }
   112→
   113→    Ok(())
   114→}
