    23→/// Gas used needs to be less than gas limit. Gas used is going to be checked after execution.
    24→#[inline]
    25→pub fn validate_header_gas<H: BlockHeader>(header: &H) -> Result<(), ConsensusError> {
    26→    if header.gas_used() > header.gas_limit() {
    27→        return Err(ConsensusError::HeaderGasUsedExceedsGasLimit {
    28→            gas_used: header.gas_used(),
    29→            gas_limit: header.gas_limit(),
    30→        })
    31→    }
    32→    // Check that the gas limit is below the maximum allowed gas limit
    33→    if header.gas_limit() > MAXIMUM_GAS_LIMIT_BLOCK {
    34→        return Err(ConsensusError::HeaderGasLimitExceedsMax { gas_limit: header.gas_limit() })
    35→    }
    36→    Ok(())
    37→}
