   275→/// Validates against the parent hash and number.
   276→///
   277→/// This function ensures that the header block number is sequential and that the hash of the parent
   278→/// header matches the parent hash in the header.
   279→#[inline]
   280→pub fn validate_against_parent_hash_number<H: BlockHeader>(
   281→    header: &H,
   282→    parent: &SealedHeader<H>,
   283→) -> Result<(), ConsensusError> {
   284→    // Parent number is consistent.
   285→    if parent.number() + 1 != header.number() {
   286→        return Err(ConsensusError::ParentBlockNumberMismatch {
   287→            parent_block_number: parent.number(),
   288→            block_number: header.number(),
   289→        })
   290→    }
   291→
   292→    if parent.hash() != header.parent_hash() {
   293→        return Err(ConsensusError::ParentHashMismatch(
   294→            GotExpected { got: header.parent_hash(), expected: parent.hash() }.into(),
   295→        ))
   296→    }
   297→
   298→    Ok(())
   299→}
